<script setup lang="ts">
/**
 * Demo: SnVideoPreview — the custom control bar vs the browser's native one.
 *
 * Left: `controls` (default) renders `SnVideoControls` — play/pause, mute,
 * seekable timeline, current / total time and fullscreen, all drawn with
 * `--sn-web-*` tokens, identical in every browser.
 * Right: `nativeControls` renders the UA's own `<video controls>` bar, which
 * is **unstylable** and differs per browser / OS (shape, order, colors,
 * captions & PiP entries). It exists only as an escape hatch.
 */
import { SnVideoPreview } from '@snui/vue-web';

/**
 * 自包含视频源（data URI，Web Platform Tests media/2x2-green.mp4，BSD-3-Clause）。
 * demo 不依赖任何外网视频源。
 */
const videoSrc =
  'data:video/mp4;base64,';
</script>

<template>
  <div class="demo-col">
    <div class="demo-row">
      <!-- 自定义控制条：默认行为 -->
      <figure class="demo-figure">
        <SnVideoPreview
          :src="videoSrc"
          :width="360"
          aspect-ratio="16 / 9"
          title="Custom controls"
          alt="Custom control bar demo"
        />
        <figcaption class="demo-caption">
          <strong>Custom controls</strong>
          <span
            >Play / pause, mute, a draggable progress bar, current / total time, fullscreen. All
            token-driven, consistent across browsers.</span
          >
        </figcaption>
      </figure>

      <!-- 浏览器原生控制条：不可美化、跨端不一致 -->
      <figure class="demo-figure">
        <SnVideoPreview
          :src="videoSrc"
          :width="360"
          aspect-ratio="16 / 9"
          :controls="false"
          native-controls
          title="Browser native control bar"
          alt="Browser native control bar demo"
        />
        <figcaption class="demo-caption">
          <strong>Browser native control bar (nativeControls)</strong>
          <span>
            Drawn by the browser,<b>cannot be styled with CSS</b>, Chrome / Safari / Firefox / iOS /
            Android vary in button count, order, colors and rounding, and may add captions or PiP
            controls. Treat this as an escape hatch only.
          </span>
        </figcaption>
      </figure>
    </div>

    <p class="demo-note">
      Interaction note: the progress bar is a native <code>&lt;input type="range"&gt;</code>,
      adjustable with arrow keys / Home / End; the fullscreen button appears only when the browser
      supports the Fullscreen API (unsupported browsers drop the button entirely instead of leaving
      a dead one).
    </p>
  </div>
</template>

